mapper.select:
select 
from house_invitations
where house_id = #{houseId}
  and invited_by_user_id = #{invitedByUserId}
  and request_id = #{requestId}
limit 1
for update

mapper.insert:
insert into house_invitations (
    house_id, phone_hash, phone_masked, invite_channel, invited_user_id, role, status, request_id,
    invited_by_user_id, accepted_user_id, expires_time, accepted_time
) values (
    #{houseId}, #{phoneHash}, #{phoneMasked}, #{inviteChannel}, #{invitedUserId}, #{role}, #{status}, #{requestId},
    #{invitedByUserId}, #{acceptedUserId}, #{expiresTime}, #{acceptedTime}
)
on duplicate key update id = id
